local addon_name, addon = ...

local L = LibStub("AceLocale-3.0"):NewLocale(addon_name, "itIT", false, true)
if not L then return end

-- Human translators the About page credits (display names only; the AI is named in the header above).
L[0] = {}

addon.translation = {
-- a600e4ad English: Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or
--     Garrote in a group, otherwise Ambush (with a dagger in the main hand). In combat: Riposte,
--     Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a
--     target about to die, and at five points Rupture when it will last (not while Blade Flurry
--     cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab (dagger) when the target is
--     not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons,
--     Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot,
--     Feint, Vanish and positioning stay with you.
[1] = "Livelli 1–70, ogni specializzazione. Dalla furtività: Premeditazione, poi Colpo Basso da solo o Garrota in gruppo, altrimenti Imboscata (con un pugnale nella mano principale). In combattimento: Risposta, Fendenti Furiosi da due punti combo (rinnovato negli ultimi due secondi), Eliminazione su un bersaglio in punto di morte, e a cinque punti Perforazione quando durerà (non mentre Vortice di Lame colpisce più bersagli), altrimenti Eliminazione. Accumula punti con Mutilazione o Pugnalata alle Spalle (pugnale) quando il bersaglio non ti attacca, altrimenti con Emorragia o Assalto Funesto. Ti ricorda i veleni mancanti, Calcio, Vortice di Lame e Scarica d'Adrenalina, Sangue Freddo ed Evasione. Esponi Armatura, Colpo ai Reni, Finta, Sparizione e il posizionamento restano a te.",
-- 5f9b3940 English: Melee DPS (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue, The
--     Burning Crusade Classic (variant key: DPS / Wowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[2] = "DPS in mischia (Wowhead)",
-- d6b11787 English: Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and
--     reminders as the simulator version, but Slice and Dice starts from one combo point and every
--     five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and
--     positioning stay with you. An alternative to the recommended simulator melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority.
[3] = "Livelli 1–70, ogni specializzazione, seguendo Wowhead. Stesse aperture dalla furtività, generatori di punti e promemoria della versione simulatore, ma Fendenti Furiosi parte da un punto combo e ogni mossa finale a cinque punti è Eliminazione: niente Perforazione. Esponi Armatura, Colpo ai Reni, Finta, Sparizione e il posizionamento restano a te. Un'alternativa alla rotazione integrata consigliata DPS in mischia di simulatore, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità.",
-- f8f8f256 English: Melee damage for every Rogue specialization from level 1 to 60, built from Icy
--     Veins, Wowhead and Warcraft Tavern. The builder follows what you know: Mutilate (Sinister
--     Strike for the fifth point), Hemorrhage, Backstab when the target is not facing you, else
--     Sinister Strike. From Stealth it opens with Premeditation, Cheap Shot when solo, Garrote for
--     Subtlety on group elites, else Ambush or Garrote. It keeps Slice and Dice and Venom up, uses
--     Expose Armor in groups on elites when no warrior has five Sunders, then spends five points on
--     Rupture (Subtlety, long fights) or Eviscerate, and never builds past five. Reminders: poisons
--     on each weapon, Kick, Blade Flurry and Adrenaline Rush on packs and elites, Cold Blood,
--     Evasion, Feint, Thistle Tea and Preparation. Left to you: Vanish, Sprint, Kidney Shot, Blind,
--     Sap and positioning. Forever restricts combat data, so Rotation Master lists this premade for
--     reference and does not select it automatically yet.
[4] = "Danni in mischia per ogni specializzazione del Ladro dal livello 1 al 60, costruita a partire da Icy Veins, Wowhead e Warcraft Tavern. Il generatore di punti segue ciò che conosci: Mutilazione (Assalto Funesto per il quinto punto), Emorragia, Pugnalata alle Spalle quando il bersaglio non ti è rivolto, altrimenti Assalto Funesto. Dalla Furtività apre con Premeditazione, Colpo Basso da solo, Garrota per Scaltrezza sulle élite in gruppo, altrimenti Imboscata o Garrota. Mantiene attivi Fendenti Furiosi e Tossina, usa Esponi Armatura in gruppo sulle élite quando nessun guerriero ha applicato cinque Spaccarmatura, poi spende cinque punti in Perforazione (Scaltrezza, combattimenti lunghi) o Eliminazione, e non accumula mai oltre cinque. Promemoria: veleni su ogni arma, Calcio, Vortice di Lame e Scarica d'Adrenalina contro gruppi ed élite, Sangue Freddo, Evasione, Finta, Tè di Cardo e Preparazione. Restano a te: Sparizione, Scatto, Colpo ai Reni, Accecamento, Tramortimento e il posizionamento. Forever limita i dati di combattimento, quindi Rotation Master elenca questa rotazione integrata a titolo di riferimento e per ora non la seleziona automaticamente.",
-- 3333c1f0 English: Subtlety, Ambush build (Warcraft Tavern)
[5] = "Scaltrezza, build Imboscata (Warcraft Tavern)",
-- 776899da English: Warcraft Tavern's Ambush/Cutthroat Subtlety build: Premeditation and Ambush on
--     every opener, Ambush again whenever Cutthroat allows it, Backstab from behind as the builder
--     (Hemorrhage when the target is facing you), Ghostly Strike on cooldown, and Slice and Dice
--     then Eviscerate at five points with no Rupture. Reminds you to Vanish for another Ambush on a
--     tanked boss. Choose it instead of the recommended Rogue premade if you took the Cutthroat
--     talents; it applies with Subtlety as your main talent tree and Cutthroat talented. Same
--     poison and cooldown reminders as the recommended premade. An alternative to the recommended
--     Rogue DPS premade, off by default: enable it and disable that one, or raise its priority.
[6] = "La build Scaltrezza Imboscata/Tagliagole di Warcraft Tavern: Premeditazione e Imboscata a ogni apertura, di nuovo Imboscata ogni volta che Tagliagole lo consente, Pugnalata alle Spalle da dietro come generatore (Emorragia quando il bersaglio ti è rivolto), Colpo Spettrale appena pronto, e Fendenti Furiosi poi Eliminazione a cinque punti, senza Perforazione. Ti ricorda di usare Sparizione per un'altra Imboscata su un boss tenuto da un difensore. Sceglila al posto della rotazione integrata consigliata per il Ladro se hai preso i talenti Tagliagole; si applica con Scaltrezza come albero dei talenti principale e Tagliagole nei talenti. Stessi promemoria per veleni e tempi di recupero della rotazione integrata consigliata. Un'alternativa alla rotazione integrata consigliata DPS del Ladro, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità.",
-- 208fc263 English: Subtlety, Garrote build (Wowhead)
[7] = "Scaltrezza, build Garrota (Wowhead)",
-- 919f756d English: Wowhead's Subtlety: Premeditation and Garrote on every opener, and Vanish (then
--     Preparation) used in the rotation to open with Garrote again once the last one has run out.
--     Slice and Dice kept up, Expose Armor in groups, Rupture as the five-point finisher,
--     Hemorrhage as the only builder. This spends Vanish, your escape, on damage: choose it
--     deliberately. It applies with Subtlety as your main talent tree, Dirty Deeds talented and
--     Premeditation known. Same poison and cooldown reminders as the recommended premade. An
--     alternative to the recommended Rogue DPS premade, off by default: enable it and disable that
--     one, or raise its priority.
[8] = "La Scaltrezza di Wowhead: Premeditazione e Garrota a ogni apertura, e Sparizione (poi Preparazione) usata nella rotazione per riaprire con Garrota una volta scaduta la precedente. Fendenti Furiosi sempre attivo, Esponi Armatura in gruppo, Perforazione come mossa finale a cinque punti, Emorragia come unico generatore. Questa variante spende Sparizione, la tua via di fuga, per i danni: sceglila consapevolmente. Si applica con Scaltrezza come albero dei talenti principale, Dirty Deeds nei talenti e Premeditazione appresa. Stessi promemoria per veleni e tempi di recupero della rotazione integrata consigliata. Un'alternativa alla rotazione integrata consigliata DPS del Ladro, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità.",
-- ea331596 English: Recommended for Assassination in Midnight. In combat the game now hides your
--     bleeds, buffs, energy, cooldown times and health from addons, so this shows Blizzard's own
--     Assisted Combat suggestion (the one-button rotation, which handles the stealth opener,
--     Garrote, Rupture, Envenom, Deathmark and Kingsbane), and stops while you cast or have no
--     enemy targeted. Reminders for what it leaves out: a lethal and a non-lethal poison and
--     Stealth between pulls, Vanish when you are out of stealth in combat, Kick on an interruptible
--     cast (it lights only where the game lets the cast be read). Health is hidden on Retail, so
--     Crimson Vial is your call.
[9] = "Consigliata per Assassinio in Midnight. In combattimento il gioco ora nasconde agli addon i tuoi sanguinamenti, gli effetti benefici, l'energia, i tempi di recupero e la salute, quindi questa rotazione mostra il suggerimento stesso dell'Assistente di Combattimento di Blizzard (la rotazione a un pulsante, che gestisce l'apertura dalla furtività, Garrota, Perforazione, Affondo Venefico, Stigma Letale e Rovina dei Re), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: un veleno letale e uno non letale e Furtività tra un ingaggio e l'altro, Sparizione quando sei fuori dalla furtività in combattimento, Calcio su un lancio interrompibile (si illumina solo dove il gioco permette di leggere il lancio). La salute è nascosta su Retail, quindi Fiala Cremisi spetta a te.",
-- 04026a9b English: Reference only, off by default: the Icy Veins and SimulationCraft order keeps
--     bleeds up by their timers, which Midnight hides in combat; energy is hidden on Retail, so its
--     energy pooling is left out. From stealth Garrote, then Ambush. Garrote in its last 30% while
--     you are not at full combo points, Rupture at 5+ in its last 30%; at 5+ combo points Coup de
--     Grace or Envenom; below, Crimson Tempest on three or more enemies, Fan of Knives on two or
--     more close by, Ambush, Mutilate. Reminders: Deathmark with both bleeds up, Kingsbane
--     alongside it, Vanish with Deathmark ready, Shiv on a Deathstalker's Mark target, Thistle Tea
--     whenever it is ready in combat, plus the shared poison, Stealth and Kick reminders.
[10] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft mantiene i sanguinamenti in base ai loro timer, che Midnight nasconde in combattimento; l'energia è nascosta su Retail, quindi l'accumulo di energia è escluso. Dalla furtività Garrota, poi Imboscata. Garrota nell'ultimo 30% della sua durata quando non hai il massimo dei punti combo, Perforazione a 5+ punti nell'ultimo 30% della sua durata; a 5+ punti combo Colpo di Grazia o Affondo Venefico; sotto, Tempesta Cremisi contro tre o più nemici, Ventaglio di Lame contro due o più nemici vicini, Imboscata, Mutilazione. Promemoria: Stigma Letale con entrambi i sanguinamenti attivi, Rovina dei Re insieme a esso, Sparizione con Stigma Letale pronto, Stilettata su un bersaglio con Marchio dell'Inseguitore della Morte, Tè di Sboccialesto ogni volta che è pronto in combattimento, più i promemoria comuni di veleni, Furtività e Calcio.",
-- bb9cc61b English: Recommended for Outlaw in Midnight. Shows Blizzard's Assisted Combat suggestion
--     (it handles the stealth opener, Roll the Bones, Blade Flurry, Adrenaline Rush, Between the
--     Eyes and the finishers), and stops while you cast or have no enemy targeted. Reminders for
--     what it leaves out: poisons and Stealth between pulls, Vanish when you are out of stealth in
--     combat, Kick. Health is hidden on Retail, so Crimson Vial is your call. Keep It Rolling stays
--     with you: the game hides how many Roll the Bones buffs you have.
[11] = "Consigliata per Fuorilegge in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard (gestisce l'apertura dalla furtività, Roulette Assassina, Vortice di Lame, Scarica d'Adrenalina, In Mezzo agli Occhi e le mosse finali), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: veleni e Furtività tra un ingaggio e l'altro, Sparizione quando sei fuori dalla furtività in combattimento, Calcio. La salute è nascosta su Retail, quindi Fiala Cremisi spetta a te. Roulette Eterna resta a te: il gioco nasconde quanti effetti benefici di Roulette Assassina hai.",
-- 3a3eecef English: Reference only, off by default: the Icy Veins, SimulationCraft and Wowhead
--     order reads Roll the Bones buffs, Opportunity stacks and energy, which Midnight hides in
--     combat. From stealth Ambush. One combo point short of full or more: Between the Eyes, Killing
--     Spree, Coup de Grace, Dispatch. Otherwise Ambush with Audacity, Pistol Shot at six
--     Opportunity stacks (three when low on combo points), Ambush, Sinister Strike. Reminders: Roll
--     the Bones with no roll up, Adrenaline Rush at two or fewer combo points, Blade Flurry kept up
--     on two or more enemies, Blade Rush, Preparation when Adrenaline Rush, Between the Eyes and
--     Blade Rush are all cooling. Keep It Rolling stays manual.
[12] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins, SimulationCraft e Wowhead legge gli effetti benefici di Roulette Assassina, i cumuli di Opportunità e l'energia, che Midnight nasconde in combattimento. Dalla furtività Imboscata. A un punto combo dal massimo o più: In Mezzo agli Occhi, Furia Omicida, Colpo di Grazia, Eliminazione. Altrimenti Imboscata con Audacia, Colpo di Pistola a sei cumuli di Opportunità (tre con pochi punti combo), Imboscata, Assalto Funesto. Promemoria: Roulette Assassina senza alcun tiro attivo, Scarica d'Adrenalina a due punti combo o meno, Vortice di Lame mantenuto contro due o più nemici, Scatto Tagliente, Preparazione quando Scarica d'Adrenalina, In Mezzo agli Occhi e Scatto Tagliente sono tutti in recupero. Roulette Eterna resta manuale.",
-- 96f6f8ea English: Recommended for Subtlety in Midnight. Shows Blizzard's Assisted Combat
--     suggestion (it handles the stealth opener, Shadow Blades, Goremaw's Bite, Shadow Dance,
--     Secret Technique and the finishers), and stops while you cast or have no enemy targeted.
--     Reminders for what it leaves out: poisons and Stealth between pulls, Kick on an interruptible
--     cast. Health is hidden on Retail, so Crimson Vial is your call.
[13] = "Consigliata per Scaltrezza in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard (gestisce l'apertura dalla furtività, Lame d'Ombra, Morso di Faucinere, Danza dell'Ombra, Tecnica Segreta e le mosse finali), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: veleni e Furtività tra un ingaggio e l'altro, Calcio su un lancio interrompibile. La salute è nascosta su Retail, quindi Fiala Cremisi spetta a te.",
-- 5fff6443 English: Reference only, off by default: the Icy Veins and SimulationCraft order holds
--     Shadow Dance for Secret Technique and reads Shadow Dance, Darkest Night and energy, which
--     Midnight hides in combat. Stealthed before the pull: Shadowstrike. One combo point short of
--     full or more: Eviscerate with Darkest Night, Secret Technique in Shadow Dance, Coup de Grace,
--     Black Powder on three or more enemies, Eviscerate. Otherwise Shadowstrike, Shuriken Storm on
--     two or more, Gloomblade or Backstab. Reminders: Goremaw's Bite in Shadow Dance, Shadow Blades
--     with Shadow Dance ready, Shadow Dance at two or fewer (or six or more) combo points when
--     Secret Technique is ready or Shadow Blades is up, Vanish out of stealth at two or fewer combo
--     points.
[14] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft riserva Danza dell'Ombra a Tecnica Segreta e legge Danza dell'Ombra, Notte Cupa e l'energia, che Midnight nasconde in combattimento. In furtività prima dell'ingaggio: Assalto d'Ombra. A un punto combo dal massimo o più: Sventramento con Notte Cupa, Tecnica Segreta durante Danza dell'Ombra, Colpo di Grazia, Polvere Nera contro tre o più nemici, Sventramento. Altrimenti Assalto d'Ombra, Tempesta di Shuriken contro due o più, Lama Tenebrosa o Pugnalata alle Spalle. Promemoria: Morso di Faucinere durante Danza dell'Ombra, Lame d'Ombra con Danza dell'Ombra pronta, Danza dell'Ombra a due punti combo o meno (o sei o più) quando Tecnica Segreta è pronta o Lame d'Ombra è attiva, Sparizione fuori dalla furtività a due punti combo o meno.",
-- 797e018d English: Recommended before you choose a specialization (while the game reports the
--     Rogue's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, the reminders every Rogue premade shares, each once
--     you know its spell. When you choose a specialization at level 10, that specialization's
--     premades take over.
[15] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Ladro). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Ladro condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione.",
-- 5fc6d26a English: Levels 1–60, every spec, also on Hardcore and Self-Found realms; built from
--     simulator, Icy Veins and Wowhead. From Stealth: Premeditation, Ambush with a dagger when the
--     target is not facing you, Cheap Shot solo, Garrote outside raids. In combat: Riposte, Slice
--     and Dice from one combo point when it is missing on an elite or a healthy target (renewed at
--     five points in its last three seconds), Expose Armor at five points in a group when you have
--     Improved Expose Armor 2/2 and nobody Sunders, a two-point Eviscerate on a target about to
--     die, otherwise Eviscerate at five and no builder past five. The builder follows what you
--     know: Ghostly Strike and Hemorrhage outside raids, Backstab with a dagger when the target is
--     not facing you, else Sinister Strike. Reminders: poisons on each weapon (Deadly on an
--     off-hand weapon when carried), Kick, Thistle Tea, Blade Flurry and Adrenaline Rush on elites
--     or two enemies with Slice and Dice up, Cold Blood at five, Evasion solo when hurt. Vanish,
--     Gouge, Preparation, Kidney Shot and racials are listed off; Feint, Sprint, Blind, Sap and
--     positioning stay with you.
[16] = "Livelli 1–60, ogni specializzazione, anche sui reami Hardcore e Self-Found; costruita a partire da simulatore, Icy Veins e Wowhead. Dalla furtività: Premeditazione, Imboscata con un pugnale quando il bersaglio non ti è rivolto, Colpo Basso da solo, Garrota fuori dalle incursioni. In combattimento: Replica Immediata, Fendenti Furiosi da un punto combo quando manca su un'élite o su un bersaglio in salute (rinnovato a cinque punti nei suoi ultimi tre secondi), Smantella Armatura a cinque punti in gruppo quando hai Smantella Armatura Migliorata 2/2 e nessuno usa Incrinatura, uno Sventramento a due punti su un bersaglio in punto di morte, altrimenti Sventramento a cinque e nessuna abilità generatrice oltre i cinque. L'abilità generatrice segue ciò che conosci: Assalto Spettrale ed Emorragia fuori dalle incursioni, Pugnalata alle Spalle con un pugnale quando il bersaglio non ti è rivolto, altrimenti Assalto Funesto. Promemoria: veleni su ciascuna arma (Veleno Mortale sull'arma della mano secondaria se la porti), Calcio, Tè di Sboccialesto, Vortice di Lame e Scarica d'Adrenalina sulle élite o contro due nemici con Fendenti Furiosi attivo, Sangue Freddo a cinque, Evasione da solo quando sei ferito. Sparizione, Sfregio Oculare, Preparazione, Colpo ai Reni e abilità razziali sono elencate ma disattivate; Finta, Scatto, Accecamento, Tramortimento e posizionamento restano a te.",
-- 64659ecb English: Melee DPS, five-point finishers (Warcraft Tavern)
[17] = "DPS in mischia, mosse finali a cinque punti (Warcraft Tavern)",
-- 6e2089d2 English: Warcraft Tavern's way, an alternative to the recommended melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority. Every finisher waits for
--     five combo points so Relentless Strikes refunds it. Slice and Dice is used from its second
--     rank (level 42) when missing or ending, otherwise Eviscerate; no low-point Slice, no
--     near-death Eviscerate and no Expose Armor (a warrior's Sunder covers it). Same openers,
--     builders and reminders as the recommended premade.
[18] = "Il metodo di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata di DPS in mischia, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Ogni mossa finale aspetta cinque punti combo così che Affondi Implacabili la rimborsi. Fendenti Furiosi viene usato dal suo secondo grado (livello 42) quando manca o sta per finire, altrimenti Sventramento; niente Fendenti Furiosi a pochi punti, niente Sventramento in punto di morte e niente Smantella Armatura (ci pensa l'Incrinatura di un guerriero). Stesse aperture, abilità generatrici e promemoria della rotazione integrata consigliata.",
-- 1bddd98c English: Swords, swing-synced Sinister Strike (simulator)
[19] = "Spade, Assalto Funesto sincronizzato con i colpi (simulatore)",
-- a0a38e03 English: The simulator "sweaty" Combat order for Sword Specialization, an alternative to
--     the recommended melee DPS premade, off by default: enable it and disable that one, or raise
--     its priority. Sinister Strike only right after a main-hand swing (2.0 seconds or more to the
--     next one, set for a 2.6–2.8 speed sword; change it in a clone), unless energy is near full or
--     the target is about to die, so the extra sword attack does not delay your swing. Eviscerate
--     at five also waits for Slice and Dice, full energy or a dying target. Otherwise as the
--     recommended premade.
[20] = "L'ordine Combattimento \"sudato\" di simulatore per Specializzazione nelle Spade, un'alternativa alla rotazione integrata consigliata di DPS in mischia, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Assalto Funesto solo subito dopo un colpo della mano primaria (2,0 secondi o più al successivo, impostato per una spada di velocità 2,6–2,8; cambialo in un duplicato), a meno che l'energia non sia quasi piena o il bersaglio stia per morire, così che l'attacco extra della spada non ritardi il tuo colpo. Anche Sventramento a cinque aspetta Fendenti Furiosi, l'energia piena o un bersaglio in punto di morte. Per il resto come la rotazione integrata consigliata.",
-- 1b2af050 English: Season of Discovery, levels 1–60 with runes as you engrave them; built from
--     simulator Phase 6, Icy Veins and Zockify Phase 8. From Stealth: Shadowstrike, Garrote in a
--     group, Ambush for a Backstab build with a dagger, Cheap Shot solo. On three or more enemies
--     fighting you: Blunderbuss, Crimson Tempest, Fan of Knives first. Then Ambush on a Cutthroat
--     proc (with a dagger), Saber Slash kept at three stacks, Poisoned Knife at four poison stacks,
--     Slice and Dice from two points (renewed from four, unless Cut to the Chase is engraved),
--     Expose Armor duty when nobody Sunders or keeps Sebacious Poison up, with Carnage engraved a
--     bleed (Crimson Tempest, else Rupture; none with Saber Slash), Envenom at five (Eviscerate
--     until you engrave it), and a builder by glove rune: Mutilate, Saber Slash, Backstab (with a
--     dagger), else Sinister Strike. Reminders: a temporary enchant on each weapon, Kick, Thistle
--     Tea, Blade Flurry, Adrenaline Rush, Cold Blood and Evasion, and with Master of Subtlety
--     engraved Vanish to renew it and Preparation.
[21] = "Season of Discovery, livelli 1–60 con le rune man mano che le incidi; costruita a partire da simulatore Fase 6, Icy Veins e Zockify Fase 8. Dalla furtività: Assalto d'Ombra, Garrota in gruppo, Imboscata per una build con Pugnalata alle Spalle con un pugnale, Colpo Basso da solo. Contro tre o più nemici che ti combattono: prima Schioppo, Tempesta Cremisi, Ventaglio di Lame. Poi Imboscata con un proc di Tagliagole (con un pugnale), Fendente di Sciabola mantenuto a tre cumuli, Coltello Avvelenato a quattro cumuli di veleno, Fendenti Furiosi da due punti (rinnovato da quattro, a meno che non sia inciso Cut to the Chase), il compito di Smantella Armatura quando nessuno usa Incrinatura né mantiene attivo Veleno Sebaceo, con Carneficina inciso un sanguinamento (Tempesta Cremisi, altrimenti Perforazione; nessuno con Fendente di Sciabola), Affondo Venefico a cinque (Sventramento finché non lo incidi), e un'abilità generatrice in base alla runa dei guanti: Mutilazione, Fendente di Sciabola, Pugnalata alle Spalle (con un pugnale), altrimenti Assalto Funesto. Promemoria: un incantamento temporaneo su ciascuna arma, Calcio, Tè di Sboccialesto, Vortice di Lame, Scarica d'Adrenalina, Sangue Freddo ed Evasione, e con Maestro di Scaltrezza inciso Sparizione per rinnovarlo e Preparazione.",
-- e2dafa09 English: Melee DPS, Rupture for Carnage (SoD, Icy Veins)
[22] = "DPS in mischia, Perforazione per Carneficina (SoD, Icy Veins)",
-- 9aaebdaf English: Icy Veins' Season of Discovery order, an alternative to the recommended Season
--     of Discovery melee DPS premade, off by default: enable it and disable that one, or raise its
--     priority. Every finisher at five combo points, first Slice and Dice when missing or ending,
--     then Rupture kept up when Carnage is engraved, then Envenom; Poisoned Knife only at five
--     poison stacks; Blunderbuss or Fan of Knives on three enemies. Same openers, builders and
--     reminders as the recommended premade; Sebacious Poison duty stays with you.
[23] = "L'ordine della Season of Discovery di Icy Veins, un'alternativa alla rotazione integrata consigliata di DPS in mischia della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Ogni mossa finale a cinque punti combo, prima Fendenti Furiosi quando manca o sta per finire, poi Perforazione mantenuta con Carneficina inciso, poi Affondo Venefico; Coltello Avvelenato solo a cinque cumuli di veleno; Schioppo o Ventaglio di Lame contro tre nemici. Stesse aperture, abilità generatrici e promemoria della rotazione integrata consigliata; il compito di Veleno Sebaceo resta a te.",
-- 0a82bcd6 English: Melee DPS, lean Envenom (SoD, Zockify)
[24] = "DPS in mischia, Affondo Venefico essenziale (SoD, Zockify)",
-- b718caf6 English: Zockify's lean Season of Discovery list, an alternative to the recommended
--     Season of Discovery melee DPS premade, off by default: enable it and disable that one, or
--     raise its priority. No bleeds and no Expose Armor. Poisoned Knife at four poison stacks,
--     Slice and Dice when missing (from two points, four with Saber Slash), Envenom at five, then
--     the glove-rune builder. The Vanish and Cold Blood burst stays with you.
[25] = "La lista essenziale della Season of Discovery di Zockify, un'alternativa alla rotazione integrata consigliata di DPS in mischia della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Niente sanguinamenti e niente Smantella Armatura. Coltello Avvelenato a quattro cumuli di veleno, Fendenti Furiosi quando manca (da due punti, quattro con Fendente di Sciabola), Affondo Venefico a cinque, poi l'abilità generatrice della runa dei guanti. La raffica di Sparizione e Sangue Freddo resta a te.",
-- a76bbe4d English: Season of Discovery tank, chosen when Just a Flesh Wound is engraved; built
--     from simulator Phase 6, Icy Veins, Zockify and Warcraft Tavern. Riposte, Main Gauche on
--     cooldown, Blade Dance from one combo point (renewed from three), Slice and Dice from three
--     (renewed from four), Fan of Knives, Crimson Tempest and Blunderbuss on three or more enemies,
--     Blunderbuss while Blade Dance is up, Eviscerate at five with both buffs up, Poisoned Knife at
--     low energy, then Saber Slash, Mutilate or Sinister Strike. Reminders: Tease in a group when
--     your target attacks someone else, Kick, Evasion below half health, Blade Flurry, Adrenaline
--     Rush, Thistle Tea and weapon poisons (the off-hand one only with an off-hand weapon).
--     Shadowstep and Sebacious Poison duty stay with you.
[26] = "Difensore della Season of Discovery, scelto quando è inciso Solo una Ferita Superficiale; costruita a partire da simulatore Fase 6, Icy Veins, Zockify e Warcraft Tavern. Replica Immediata, Doppio Attacco appena pronto, Lame Danzanti da un punto combo (rinnovata da tre), Fendenti Furiosi da tre (rinnovato da quattro), Ventaglio di Lame, Tempesta Cremisi e Schioppo contro tre o più nemici, Schioppo mentre Lame Danzanti è attiva, Sventramento a cinque con entrambi gli effetti benefici attivi, Coltello Avvelenato con poca energia, poi Fendente di Sciabola, Mutilazione o Assalto Funesto. Promemoria: Beffa in gruppo quando il tuo bersaglio attacca qualcun altro, Calcio, Evasione sotto metà della salute, Vortice di Lame, Scarica d'Adrenalina, Tè di Sboccialesto e veleni per le armi (quello della mano secondaria solo con un'arma nella mano secondaria). Passo nell'Ombra e il compito di Veleno Sebaceo restano a te.",
-- a78d028d English: Recommended for Assassination, from level 10 to 90 (simulator and Wowhead for
--     Phase 5, with Icy Veins' leveling steps). Opens from Stealth with Cheap Shot when solo,
--     otherwise Mutilate (Dispatch on Blindside, with a dagger). Keeps Slice and Dice up (Envenom
--     refreshes it from level 60) and Rupture on the target, spends five points on Envenom while
--     Rupture lasts and four points to keep the Envenom buff rolling when you do not have
--     Anticipation, then Marked for Death, Dispatch below 35% or on Blindside (it needs a dagger in
--     the main hand), and Mutilate. Against four or more enemies fighting you: Slice and Dice,
--     Crimson Tempest at seven, Rupture, Envenom and Fan of Knives; tabbing Rupture onto other
--     targets is up to you. Solo it adds Recuperate and a Kidney Shot when you are low. Reminders:
--     poisons, Kick, Vendetta on long fights, Shadow Blades with Vendetta, Vanish and Preparation
--     inside Vendetta, Shadowstep from range, Evasion solo. Left to you: Tricks of the Trade and
--     Expose Armor (listed but off), Feint, Sprint and positioning.
[27] = "Consigliata per Assassinio, dal livello 10 al 90 (simulatore e Wowhead per la Fase 5, con i passaggi di livellamento di Icy Veins). Apre dalla furtività con Colpo Basso quando giochi da solo, altrimenti Mutilazione (Eliminazione con Lato Cieco, con un pugnale). Mantiene attivi Fendenti Furiosi (Affondo Venefico lo rinnova dal livello 60) e Perforazione sul bersaglio, spende cinque punti in Affondo Venefico finché dura Perforazione e quattro punti per mantenere attivo l'effetto benefico di Affondo Venefico quando non hai Anticipazione, poi Marchio della Morte, Eliminazione sotto il 35% o con Lato Cieco (richiede un pugnale nella mano primaria), e Mutilazione. Contro quattro o più nemici che ti combattono: Fendenti Furiosi, Tempesta Cremisi a sette nemici, Perforazione, Affondo Venefico e Ventaglio di Lame; spostare Perforazione su altri bersagli con Tab spetta a te. Da solo aggiunge Recupero Vitale e un Colpo ai Reni quando sei in difficoltà. Promemoria: veleni, Calcio, Ritorsione nei combattimenti lunghi, Lame d'Ombra con Ritorsione, Sparizione e Preparazione durante Ritorsione, Passo nell'Ombra dalla distanza, Evasione da solo. Lasciati a te: Trucchi del Mestiere e Smantella Armatura (elencati ma disattivati), Finta, Scatto e posizionamento.",
-- 446abf99 English: Envenom at five (Icy Veins)
[28] = "Affondo Venefico a cinque (Icy Veins)",
-- 584543ab English: Off by default. The Icy Veins and Method order: Vanish on cooldown for a
--     stealthed Mutilate, Vendetta on cooldown when the fight is long enough, Envenom only at five
--     points, Rupture kept up, Dispatch below 35% or on Blindside, Mutilate. Four to eight enemies:
--     Fan of Knives with Rupture at three points or more; nine or more: Fan of Knives and Envenom
--     only. The recommended Assassination premade follows the newer Phase 5 advice instead; to use
--     this one, enable it and disable the recommended one.
[29] = "Disattivata per impostazione predefinita. L'ordine di Icy Veins e Method: Sparizione appena pronta per una Mutilazione dalla furtività, Ritorsione appena pronta quando il combattimento è abbastanza lungo, Affondo Venefico solo a cinque punti, Perforazione sempre attiva, Eliminazione sotto il 35% o con Lato Cieco, Mutilazione. Da quattro a otto nemici: Ventaglio di Lame con Perforazione a tre punti o più; nove o più: solo Ventaglio di Lame e Affondo Venefico. La rotazione integrata Assassinio consigliata segue invece i consigli più recenti della Fase 5; per usare questa, attivala e disattiva quella consigliata.",
-- e298e91f English: Recommended for Combat, from level 10 to 90 (Wowhead and simulator for Phase
--     5). Since the Siege of Orgrimmar patch Sinister Strike costs 50 energy, so Revealing Strike
--     is the builder and Sinister Strike is used only under Bloodlust or Heroism with Adrenaline
--     Rush (and before level 20). Opens with Cheap Shot solo, otherwise Ambush. Keeps Slice and
--     Dice up from two points and Revealing Strike on the target, spends five points only while
--     Revealing Strike is up (Slice and Dice, Rupture on a long single-target fight without Blade
--     Flurry, Eviscerate) and waits for energy at five. Against eight or more enemies: Slice and
--     Dice, Crimson Tempest and Fan of Knives. Solo it adds Recuperate and Kidney Shot. Reminders:
--     poisons, Kick, Blade Flurry on against two or more enemies and off again, Adrenaline Rush at
--     low energy with Shadow Blades, Killing Spree, Vanish and Preparation for Ambush in Deep
--     Insight, Shadowstep, Evasion solo. Left to you: Tricks of the Trade and Expose Armor (listed
--     but off), Feint and positioning behind the target for Ambush.
[30] = "Consigliata per Combattimento, dal livello 10 al 90 (Wowhead e simulatore per la Fase 5). Dalla patch dell'Assedio di Orgrimmar Assalto Funesto costa 50 di energia, quindi Assalto Rivelatore è l'abilità generatrice e Assalto Funesto viene usato solo durante Brama di Sangue o Eroismo con Scarica d'Adrenalina (e prima del livello 20). Apre con Colpo Basso da solo, altrimenti Imboscata. Mantiene attivi Fendenti Furiosi da due punti e Assalto Rivelatore sul bersaglio, spende cinque punti solo mentre Assalto Rivelatore è attivo (Fendenti Furiosi, Perforazione in un lungo combattimento contro un solo bersaglio senza Vortice di Lame, Sventramento) e a cinque aspetta l'energia. Contro otto o più nemici: Fendenti Furiosi, Tempesta Cremisi e Ventaglio di Lame. Da solo aggiunge Recupero Vitale e Colpo ai Reni. Promemoria: veleni, Calcio, Vortice di Lame attivato contro due o più nemici e poi di nuovo disattivato, Scarica d'Adrenalina con poca energia insieme a Lame d'Ombra, Furia Omicida, Sparizione e Preparazione per Imboscata durante Consapevolezza Profonda, Passo nell'Ombra, Evasione da solo. Lasciati a te: Trucchi del Mestiere e Smantella Armatura (elencati ma disattivati), Finta e il posizionamento dietro al bersaglio per Imboscata.",
-- 44b84c55 English: Sinister Strike builder (Icy Veins)
[31] = "Assalto Funesto come generatore (Icy Veins)",
-- 610b2100 English: Off by default, and superseded for Phase 5. The Icy Veins, Warcraft Tavern,
--     Method and wowtbc.gg order from before the Siege of Orgrimmar patch: Slice and Dice,
--     Revealing Strike kept up, five-point Rupture on a long single-target fight and Eviscerate,
--     with Sinister Strike as the builder. Same reminders and pack play as the recommended Combat
--     premade. Choose it only if you follow those guides; enable it and disable the recommended
--     one.
[32] = "Disattivata per impostazione predefinita, e superata per la Fase 5. L'ordine di Icy Veins, Warcraft Tavern, Method e wowtbc.gg di prima della patch dell'Assedio di Orgrimmar: Fendenti Furiosi, Assalto Rivelatore sempre attivo, Perforazione a cinque punti in un lungo combattimento contro un solo bersaglio e Sventramento, con Assalto Funesto come abilità generatrice. Stessi promemoria e gestione dei gruppi della rotazione integrata Combattimento consigliata. Sceglila solo se segui quelle guide; attivala e disattiva quella consigliata.",
-- 972be132 English: Anticipation (Hekili)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue,
--     Mists of Pandaria Classic (variant key: Combat / Hekili). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[33] = "Anticipazione (Hekili)",
-- a677df00 English: Off by default. The Hekili MoP order for Combat with Anticipation: Revealing
--     Strike is the only builder, even under Bloodlust; finishers wait for Deep Insight, four
--     Anticipation charges or Shadow Blades coming back, then Slice and Dice, Rupture on one or two
--     long-lived targets, Crimson Tempest at seven enemies and Eviscerate; Slice and Dice is
--     refreshed early at 11 Bandit's Guile stacks; Fan of Knives from four enemies. It applies only
--     with Anticipation talented. Enable it and disable the recommended Combat premade to use it.
[34] = "Disattivata per impostazione predefinita. L'ordine MoP di Hekili per Combattimento con Anticipazione: Assalto Rivelatore è l'unica abilità generatrice, anche durante Brama di Sangue; le mosse finali aspettano Consapevolezza Profonda, quattro cariche di Anticipazione o il ritorno di Lame d'Ombra, poi Fendenti Furiosi, Perforazione su uno o due bersagli longevi, Tempesta Cremisi a sette nemici e Sventramento; Fendenti Furiosi viene rinnovato in anticipo a 11 cumuli di Astuzia del Bandito; Ventaglio di Lame da quattro nemici. Si applica solo con il talento Anticipazione. Per usarla attivala e disattiva la rotazione integrata Combattimento consigliata.",
-- c2f73eb9 English: Recommended for Subtlety with Shadow Focus, from level 10 to 90 (simulator and
--     Wowhead for Phase 5). In Stealth or Shadow Dance: Premeditation, Slice and Dice before the
--     pull, finishers at five points, Ambush, Garrote. Outside: Slice and Dice; at five points
--     Slice and Dice and Rupture when they are about to drop, Eviscerate while both last; Marked
--     for Death; Hemorrhage to keep its bleed; Backstab (with a dagger) when the target is not
--     attacking you, otherwise Hemorrhage. Against three or more enemies: Slice and Dice, Crimson
--     Tempest, Eviscerate and Fan of Knives. Solo it adds Recuperate and Kidney Shot. Reminders:
--     poisons, Kick, Shadow Dance at 75 energy with Slice and Dice and Rupture up, Vanish when Find
--     Weakness is ending, Preparation, Shadow Blades outside Dance and Stealth, Shadowstep, Evasion
--     solo. Left to you: standing behind the target (RM cannot see facing), Tricks of the Trade and
--     Expose Armor (listed but off).
[35] = "Consigliata per Scaltrezza con Concentrazione dell'Ombra, dal livello 10 al 90 (simulatore e Wowhead per la Fase 5). In furtività o durante Danza dell'Ombra: Premeditazione, Fendenti Furiosi prima dell'ingaggio, mosse finali a cinque punti, Imboscata, Garrota. Fuori: Fendenti Furiosi; a cinque punti Fendenti Furiosi e Perforazione quando stanno per scadere, Sventramento finché durano entrambi; Marchio della Morte; Emorragia per mantenerne il sanguinamento; Pugnalata alle Spalle (con un pugnale) quando il bersaglio non ti sta attaccando, altrimenti Emorragia. Contro tre o più nemici: Fendenti Furiosi, Tempesta Cremisi, Sventramento e Ventaglio di Lame. Da solo aggiunge Recupero Vitale e Colpo ai Reni. Promemoria: veleni, Calcio, Danza dell'Ombra a 75 di energia con Fendenti Furiosi e Perforazione attivi, Sparizione quando Individuazione Debolezze sta per finire, Preparazione, Lame d'Ombra fuori da Danza e furtività, Passo nell'Ombra, Evasione da solo. Lasciati a te: stare dietro al bersaglio (RM non può vedere l'orientamento), Trucchi del Mestiere e Smantella Armatura (elencati ma disattivati).",
-- a7cbb172 English: Subterfuge (Warcraft Tavern)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue,
--     Mists of Pandaria Classic (variant key: Subtlety / WarcraftTavern). Names in parentheses
--     (guide or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics,
--     Warcraft Tavern) are proper names and stay unchanged.
[36] = "Sotterfugio (Warcraft Tavern)",
-- 01394d1f English: Chosen automatically instead of the Shadow Focus premade when your tier-1
--     talent is Subterfuge (Warcraft Tavern's build). Premeditation and Slice and Dice before the
--     pull; in Stealth, Shadow Dance or the Subterfuge linger, finishers at five points and then
--     Ambush as often as it lands. Two or three enemies: keep Rupture up and spend five points on
--     Crimson Tempest instead of Eviscerate; four or more add Fan of Knives. One target: Slice and
--     Dice, Rupture, Eviscerate, Hemorrhage for its bleed, Backstab from behind with a dagger, else
--     Hemorrhage. Shadow Dance and Vanish are reminders at 60 energy with Slice and Dice up; timing
--     them to trinket procs, as Tavern suggests, is up to you.
[37] = "Scelta automaticamente al posto della rotazione integrata con Concentrazione dell'Ombra quando il tuo talento di primo livello è Sotterfugio (la build di Warcraft Tavern). Premeditazione e Fendenti Furiosi prima dell'ingaggio; in furtività, durante Danza dell'Ombra o nella persistenza di Sotterfugio, mosse finali a cinque punti e poi Imboscata ogni volta che va a segno. Due o tre nemici: mantieni attiva Perforazione e spendi cinque punti in Tempesta Cremisi invece di Sventramento; quattro o più aggiungono Ventaglio di Lame. Un bersaglio: Fendenti Furiosi, Perforazione, Sventramento, Emorragia per il suo sanguinamento, Pugnalata alle Spalle da dietro con un pugnale, altrimenti Emorragia. Danza dell'Ombra e Sparizione sono promemoria a 60 di energia con Fendenti Furiosi attivo; sincronizzarle con i proc dei monili, come suggerisce Tavern, spetta a te.",
-- 60f6bea5 English: For levels 1 to 9, or a rogue who has not chosen a specialization yet; each
--     specialization's premade takes over once you pick one. Opens from Stealth with Cheap Shot
--     when solo, Ambush or Sinister Strike; suggests Stealth out of combat; Slice and Dice from two
--     points, Recuperate and Kidney Shot when solo and hurt, Eviscerate at four points (two when
--     the target is about to die), Sinister Strike. Reminders: poisons once learned, Kick, Evasion
--     solo.
[38] = "Per i livelli da 1 a 9, o per un ladro che non ha ancora scelto una specializzazione; la rotazione integrata di ciascuna specializzazione subentra appena ne scegli una. Apre dalla furtività con Colpo Basso quando giochi da solo, Imboscata o Assalto Funesto; suggerisce Furtività fuori dal combattimento; Fendenti Furiosi da due punti, Recupero Vitale e Colpo ai Reni quando sei da solo e ferito, Sventramento a quattro punti (due quando il bersaglio sta per morire), Assalto Funesto. Promemoria: veleni una volta appresi, Calcio, Evasione da solo.",
}
